#[cfg(test)]
mod tests {
    use super::*;

    fn merged(a: &[i32], b: &[i32]) -> Vec<i32> {
        ListNode::to_vec(&merge_sorted_lists(ListNode::from_vec(a), ListNode::from_vec(b)))
    }

    #[test]
    fn basic() {
        assert_eq!(merged(&[1, 4, 6], &[2, 4, 9]), vec![1, 2, 4, 4, 6, 9]);
    }

    #[test]
    fn one_empty() {
        assert_eq!(merged(&[], &[0, 3]), vec![0, 3]);
        assert_eq!(merged(&[5], &[]), vec![5]);
    }

    #[test]
    fn both_empty() {
        assert_eq!(merge_sorted_lists(None, None), None);
        assert_eq!(merged(&[], &[1]), vec![1]);
    }

    #[test]
    fn disjoint_ranges() {
        assert_eq!(merged(&[10, 11], &[1, 2, 3]), vec![1, 2, 3, 10, 11]);
    }

    #[test]
    fn negatives_and_duplicates() {
        assert_eq!(merged(&[-3, -3, 0], &[-3, 1]), vec![-3, -3, -3, 0, 1]);
    }
}
